    Node head, tail;
    int size = 0;

    // Add at beginning
    void addFirst(int data) { /* ... */ }

    // Add at end
    void addLast(int data) { /* ... */ }

    // CASE 1: Delete first node
    void deleteFirst() { /* implemented above */ }

    // CASE 2: Delete last node
    void deleteLast() { /* implemented above */ }

    // CASE 3: Delete at specific index
    void deleteAtIndex(int index) { /* implemented above */ }

    // Display the list
    void display() {
        Node temp = head;
